import * as THREE from './vendor/three.module.js';
import { OrbitControls } from './vendor/OrbitControls.js';
import { createCharacter } from './rig.js?rev=tongue-hair-3';
import { createController, parameterSchema, presets, sampleSequences } from './controller.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const viewport = $('#viewport');
const sliderElements = new Map();
let renderer, scene, camera, orbit, rig;
let currentGroup = 'lips', wire = false, cutaway = false, playing = false, sequenceStart = 0, sequenceDuration = 0, playToken = 0;
let activeFrames = sampleSequences.hello.frames;
const groups = { lips:['jawOpen','lipRound','lipSpread','lipClose','upperLipRaise','lowerLipDepress'], tongue:['tongueOut','tongueUp','tongueBack','tongueLeft'], cheeks:['cheekPuffLeft','cheekPuffRight','cheekRaiseLeft','cheekRaiseRight','blinkLeft','blinkRight','smile'] };
const shortNames = {jawOpen:'jaw',lipRound:'round',lipSpread:'spread',lipClose:'close',upperLipRaise:'upper',lowerLipDepress:'lower',tongueOut:'out',tongueUp:'up',tongueBack:'back',tongueLeft:'L ↔ R',cheekPuffLeft:'puff L',cheekPuffRight:'puff R',cheekRaiseLeft:'raise L',cheekRaiseRight:'raise R',blinkLeft:'blink L',blinkRight:'blink R',smile:'smile'};
let lastState = Object.fromEntries(parameterSchema.map(p=>[p.key,p.default]));
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function renderState(state){lastState=state;rig?.update(state);for(const [key,els] of sliderElements){const p=parameterSchema.find(p=>p.key===key),v=state[key];els.input.value=v;els.output.textContent=v.toFixed(2);els.input.style.setProperty('--fill',`${100*(v-p.min)/(p.max-p.min)}%`);}}
const controller = createController(renderState);
function stopPlaying(){playToken++;controller.stop();playing=false;$('#playLabel').textContent='播放动作';$('#playIcon').textContent='▶';$$('#sequenceTrack span').forEach(el=>el.classList.remove('active'));}
function markPreset(id){$$('.preset').forEach(b=>b.classList.toggle('selected',b.dataset.preset===id));}
function drawSliders(){const container=$('#sliders');container.replaceChildren();sliderElements.clear();for(const key of groups[currentGroup]){const p=parameterSchema.find(p=>p.key===key);const row=document.createElement('div');row.className='slider-row';const label=document.createElement('label');label.className='slider-label';label.htmlFor=`param-${key}`;const text=document.createElement('span');text.textContent=p.label;const small=document.createElement('small');small.textContent=shortNames[key];text.append(small);const output=document.createElement('output');output.htmlFor=`param-${key}`;output.value=lastState[key].toFixed(2);label.append(text,output);const input=document.createElement('input');Object.assign(input,{type:'range',id:`param-${key}`,min:p.min,max:p.max,step:.01,value:lastState[key]});input.setAttribute('aria-label',p.label);input.style.setProperty('--fill',`${100*(lastState[key]-p.min)/(p.max-p.min)}%`);input.addEventListener('input',()=>{stopPlaying();markPreset(null);$('#presetHint').replaceChildren(document.createTextNode('正在手动调整模型姿态。'));controller.setPose({[key]:Number(input.value)},{duration:0});});row.append(label,input);container.append(row);sliderElements.set(key,{input,output});}}
drawSliders();$('#channelCount').textContent=parameterSchema.length;
$$('[data-group]').forEach(b=>b.addEventListener('click',()=>{currentGroup=b.dataset.group;$$('[data-group]').forEach(t=>{const active=t===b;t.classList.toggle('selected',active);t.setAttribute('aria-selected',active);});drawSliders();}));
for(const p of presets){const b=document.createElement('button');b.className=`preset ${p.id==='neutral'?'selected':''}`;b.dataset.preset=p.id;b.setAttribute('aria-label',`${p.label} ${p.ipa} ${p.word}`);const symbol=document.createElement('strong');symbol.textContent=p.id==='neutral'?'⌣':p.ipa;symbol.classList.toggle('neutral-icon',p.id==='neutral');const word=document.createElement('small');word.textContent=p.id==='neutral'?'自然':p.word;b.append(symbol,word);b.addEventListener('click',()=>{stopPlaying();controller.setViseme(p.id);markPreset(p.id);$('#presetHint').textContent=`${p.ipa? p.ipa+' · ':''}${p.hint}`;});$('#presets').append(b);}
$('#resetPose').addEventListener('click',()=>{stopPlaying();controller.reset();markPreset('neutral');$('#presetHint').textContent='自然放松，回到初始口型。';});
function drawTrack(frames){const track=$('#sequenceTrack');track.replaceChildren();frames.forEach((f,i)=>{const el=document.createElement('span');el.textContent=presets.find(p=>p.id===f.viseme)?.ipa || `·`;el.title=`第 ${i+1} 帧 · ${f.duration} ms`;track.append(el);});}
drawTrack(activeFrames);
$('#sequenceSelect').addEventListener('change',()=>{stopPlaying();activeFrames=sampleSequences[$('#sequenceSelect').value]?.frames || activeFrames;drawTrack(activeFrames);});
$('#speed').addEventListener('change',()=>{if(playing){stopPlaying();toast('已停止，按新速度重新播放');}});
$('#playSequence').addEventListener('click',async()=>{if(playing){stopPlaying();return;}const token=++playToken;playing=true;markPreset(null);$('#playIcon').textContent='■';$('#playLabel').textContent='停止动作';const speed=Number($('#speed').value);sequenceStart=performance.now();sequenceDuration=activeFrames.reduce((sum,f)=>sum+f.duration,0)/speed;try{const result=await controller.playSequence(activeFrames,{speed});if(token===playToken){playing=false;$('#playIcon').textContent='▶';$('#playLabel').textContent='播放动作';$$('#sequenceTrack span').forEach(el=>el.classList.remove('active'));if(result.status==='completed'){$('#presetHint').textContent='动作序列播放完成，可以继续调节任意部位。';}}}catch(e){stopPlaying();toast(e.message);}});
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('#exportPose').addEventListener('click',()=>{download('xiaoyan-pose.json',JSON.stringify({version:'0.1',character:'xiaoyan',pose:controller.getState()},null,2));toast('已导出当前姿态 JSON');});
const snippets={pose:`// 舌头、嘴唇、脸颊的独立控制\nawait window.articulation.setPose({\n  jawOpen: 0.65,\n  tongueOut: 0.4,\n  lipRound: 0.2,\n  cheekPuffLeft: 0.35\n}, { duration: 300 });`,viseme:`// 由音素时间轴驱动预设口型\nawait window.articulation.setViseme('th', {\n  duration: 180\n});\n\n// 读取当前的所有动作参数\nconst pose = window.articulation.getState();`,sequence:`// 每帧时长含平滑过渡与停留，单位为毫秒\nawait window.articulation.playSequence([\n  { viseme: 'aa', duration: 400 },\n  { viseme: 'l', duration: 250 },\n  { viseme: 'oh', duration: 500 },\n  { viseme: 'neutral', duration: 250 }\n], { speed: 1, loop: false });`};
let docTab='pose';$('#apiCode').textContent=snippets.pose;
$$('[data-doc]').forEach(b=>b.addEventListener('click',()=>{docTab=b.dataset.doc;$$('[data-doc]').forEach(t=>t.classList.toggle('selected',b===t));$('#apiCode').textContent=snippets[docTab];}));
for(const id of ['docsButton','apiButton'])$('#'+id).addEventListener('click',()=>$('#docsDialog').showModal());$('#referenceButton').addEventListener('click',()=>$('#referenceDialog').showModal());
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#copyCode').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(snippets[docTab]);toast('接口示例已复制');}catch{toast('请直接选择示例代码进行复制');}});
$('#downloadConfig').addEventListener('click',()=>{download('articulation-api.json',JSON.stringify({version:'0.1',global:'window.articulation',parameters:parameterSchema,presets,sampleSequences,examples:snippets},null,2));toast('接口说明已下载');});
$('#importSequence').addEventListener('click',()=>$('#sequenceFile').click());$('#sequenceFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1e6)throw Error('请选择小于 1 MB 的动作 JSON');const data=JSON.parse(await file.text());const frames=Array.isArray(data)?data:data.frames;if(!Array.isArray(frames)||!frames.length||frames.length>500)throw Error('动作需要包含 1–500 帧');for(const f of frames){if(!f || !Number.isFinite(f.duration)||f.duration<0||f.duration>60000)throw Error('每帧需要 0–60000 ms 的 duration');const hasPose=Object.hasOwn(f,'pose'),hasViseme=Object.hasOwn(f,'viseme');if(hasPose===hasViseme)throw Error('每帧必须且只能包含 viseme 或 pose 之一');if(hasViseme&&!presets.some(p=>p.id===f.viseme))throw Error(`未知口型：${f.viseme}`);if(hasPose){if(f.pose===null||typeof f.pose!=='object'||Array.isArray(f.pose))throw Error('pose 需要为参数对象');for(const[k,v]of Object.entries(f.pose)){if(!parameterSchema.some(p=>p.key===k)||typeof v!=='number'||!Number.isFinite(v))throw Error(`无效的动作参数：${k}`);}}}stopPlaying();activeFrames=frames;let opt=$('#sequenceSelect option[value="custom"]');if(!opt){opt=document.createElement('option');opt.value='custom';$('#sequenceSelect').append(opt);}opt.textContent=file.name.replace(/\.json$/i,'');$('#sequenceSelect').value='custom';drawTrack(frames);$('#docsDialog').close();toast('已载入动作序列，点击播放动作预览');}catch(e){toast(`无法导入：${e.message}`);}finally{e.target.value='';}});
const table=document.createElement('table');table.innerHTML='<thead><tr><th>参数名</th><th>动作</th><th>范围</th></tr></thead>';const tbody=document.createElement('tbody');for(const p of parameterSchema){const tr=document.createElement('tr');for(const t of[p.key,p.label,`${p.min} → ${p.max}`]){const td=document.createElement('td');td.textContent=t;tr.append(td);}tbody.append(tr);}table.append(tbody);$('#schemaTable').append(table);
window.articulation=Object.freeze({version:'0.1',protocolVersion:controller.protocolVersion,parameters:parameterSchema,presets,setPose:controller.setPose,setViseme:controller.setViseme,playSequence:controller.playSequence,getState:controller.getState,reset:controller.reset,stop:controller.stop,destroy:controller.destroy,events:controller.events});

try{
 scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(37,1,.1,100);camera.position.set(0,.05,8.7);
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.14;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;viewport.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','可拖动旋转的三维卡通男孩模型');renderer.domElement.setAttribute('role','img');
 scene.add(new THREE.HemisphereLight(0xfffbea,0x728a6d,2.3));const key=new THREE.DirectionalLight(0xffe8d0,3.2);key.position.set(-3,5,6);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-4;key.shadow.camera.right=4;key.shadow.camera.top=4;key.shadow.camera.bottom=-4;key.shadow.normalBias=.04;key.shadow.bias=-.001;scene.add(key);const fill=new THREE.DirectionalLight(0xd9eeff,2);fill.position.set(4,1,3);scene.add(fill);const rim=new THREE.DirectionalLight(0xf1ffe0,3);rim.position.set(1,4,-3);scene.add(rim);
 rig=createCharacter();scene.add(rig.group);rig.update(lastState);rig.group.traverse(obj=>{if(obj.isMesh){obj.castShadow=true;obj.receiveShadow=true;}});
 const floor=new THREE.Mesh(new THREE.CircleGeometry(2.1,72),new THREE.ShadowMaterial({color:0x567647,opacity:.14}));floor.rotation.x=-Math.PI/2;floor.position.y=-2.67;scene.add(floor);
 orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(0,-.23,0);orbit.enableDamping=true;orbit.dampingFactor=.075;orbit.enablePan=false;orbit.minDistance=4.1;orbit.maxDistance=12;orbit.minPolarAngle=.3;orbit.maxPolarAngle=Math.PI-.45;orbit.addEventListener('start',()=>{$$('[data-view]').forEach(b=>b.classList.remove('selected'));});
 function resize(){const{width,height}=viewport.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(viewport);resize();$('#loading').remove();
 let cameraTween=null;function setView(view){let target=orbit.target.clone();let distance=view==='side'?8.4:8.7;const views={front:new THREE.Vector3(0,.05,distance),threequarter:new THREE.Vector3(5.7,.4,6.6),side:new THREE.Vector3(8.6,.1,.15)};cameraTween={start:performance.now(),from:camera.position.clone(),to:views[view]||views.front};$$('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));}
 $$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#resetCamera').addEventListener('click',()=>{orbit.target.set(0,-.23,0);setView('front');});$('#zoomIn').addEventListener('click',()=>{cameraTween=null;const v=camera.position.clone().sub(orbit.target);v.setLength(Math.max(orbit.minDistance,v.length()*.85));camera.position.copy(orbit.target).add(v);});$('#zoomOut').addEventListener('click',()=>{cameraTween=null;const v=camera.position.clone().sub(orbit.target);v.setLength(Math.min(orbit.maxDistance,v.length()*1.15));camera.position.copy(orbit.target).add(v);});
 $('#wireButton').addEventListener('click',()=>{wire=!wire;rig.setWireframe(wire);$('#wireButton').setAttribute('aria-pressed',wire);});$('#cutawayButton').addEventListener('click',()=>{cutaway=!cutaway;rig.setCutaway(cutaway);$('#cutawayButton').setAttribute('aria-pressed',cutaway);if(cutaway){stopPlaying();controller.setViseme('th');markPreset('th');$('#presetHint').textContent='口腔透视：观察舌头与牙齿的相对位置，可手动调整舌头参数。';currentGroup='tongue';$$('[data-group]').forEach(t=>{const a=t.dataset.group==='tongue';t.classList.toggle('selected',a);t.setAttribute('aria-selected',a);});drawSliders();}});
 $('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.preview-panel').requestFullscreen();}catch{toast('当前浏览器不支持全屏预览');}});
 function animate(t){requestAnimationFrame(animate);if(cameraTween){const a=Math.min((t-cameraTween.start)/650,1),e=a*a*(3-2*a);camera.position.lerpVectors(cameraTween.from,cameraTween.to,e);if(a===1)cameraTween=null;}orbit.update();if(playing){const speed=Number($('#speed').value);let elapsed=(t-sequenceStart)*speed,idx=0;while(idx<activeFrames.length-1&&elapsed>=activeFrames[idx].duration){elapsed-=activeFrames[idx].duration;idx++;}$$('#sequenceTrack span').forEach((s,i)=>s.classList.toggle('active',i===idx));}renderer.render(scene,camera);}requestAnimationFrame(animate);
 window.dispatchEvent(new CustomEvent('articulation:ready',{detail:{version:'0.1',channels:parameterSchema.length}}));document.body.dataset.ready='true';
}catch(e){console.error(e);$('#loading').textContent='三维视图未能加载。请使用支持 WebGL 2 的浏览器重试。';$('#loading').style.padding='30px';toast('模型加载遇到问题，请刷新网页');}
